#!/usr/bin/env bash
# Creates the `oncall` role and database in the compose Postgres (idempotent). The password comes from .env
# (ONCALL_PG_PASSWORD, generated by gen_env.sh) and is never printed.
set -euo pipefail
cd "$(dirname "$0")/../.."
set -a; . ./.env; set +a
: "${ONCALL_PG_PASSWORD:?run oncall/tools/gen_env.sh first}"
psqlx() { docker exec -i postgres psql -U payments -d postgres -v ON_ERROR_STOP=1 -q "$@"; }
if ! psqlx -tAc "select 1 from pg_roles where rolname='oncall'" | grep -q 1; then
  psqlx -c "create role oncall login password '${ONCALL_PG_PASSWORD}'"
else
  psqlx -c "alter role oncall password '${ONCALL_PG_PASSWORD}'"
fi
if ! psqlx -tAc "select 1 from pg_database where datname='oncall'" | grep -q 1; then
  psqlx -c "create database oncall owner oncall"
fi
echo "oncall database ready"
